INSERT INTO series (id, actors, genre, imdb_rating, poster, season, sinopse, title)
VALUES
    ('1', 'Aaron Pierre, Kyle Chandler, Kelly Macdonald', 'ACTION', '8.4', 'https://m.media-amazon.com/images/M/MV5BM2ZjZDNlNDgtMjJlMy00NGRjLThlMGEtM2U4N2E4MDUwNjNmXkEyXkFqcGc@._V1_QL75_UY562_CR28,0,380,562_.jpg', '2', 'Lanterns follows new recruit John Stewart and Lantern legend Hal Jordan, two intergalactic cops drawn into a dark, Earth-based mystery as they investigate a murder in the American heartland.', 'Lanterns'),
    ('4', 'Simon Baker, Robin Tunney, Tim Kang', 'CRIME', '8.2', 'https://m.media-amazon.com/images/M/MV5BMTQ5OTgzOTczM15BMl5BanBnXkFtZTcwMDM2OTY4MQ@@._V1_SX300.jpg', '7', 'Famous "psychic", Patrick Jane, outs himself as a fake, and using his heightened observational skills and impeccable knowledge of the human psyche, he works with the police so he can find "Red John", the madman who killed his family.', 'The Mentalist'),
    ('5', 'Emilia Clarke, Peter Dinklage, Kit Harington', 'ACTION', '9.2', 'https://m.media-amazon.com/images/M/MV5BMTNhMDJmNmYtNDQ5OS00ODdlLWE0ZDAtZTgyYTIwNDY3OTU3XkEyXkFqcGc@._V1_QL75_UX380_CR0,3,380,562_.jpg', '8', 'Nine noble families fight for control over the lands of Westeros, while an ancient enemy returns after being dormant for millennia.', 'Game of Thrones'),
    ('7', 'Bryan Cranston, Aaron Paul, Anna Gunn', 'CRIME', '9.5', 'https://m.media-amazon.com/images/M/MV5BOWE4NTc3YmYtNmU2Mi00ZjhkLWE1MTItZmM1M2U1ODU3YjFlXkEyXkFqcGc@._V1_QL75_UY562_CR2,0,380,562_.jpg', '5', 'A chemistry teacher diagnosed with inoperable lung cancer turns to manufacturing and selling methamphetamine with a former student to secure his family''s future.', 'Breaking Bad'),
    ('8', 'Scott Grimes, Damian Lewis, Ron Livingston', 'ACTION', '9.4', 'https://m.media-amazon.com/images/M/MV5BMTQ3NTdmOTEtZTRmMi00NTg5LWI5NmUtYTNiOTc0ZmNkODU0XkEyXkFqcGc@._V1_SX300.jpg', '1', 'The story of Easy Company of the U.S. Army 101st Airborne Division and their mission in World War II Europe, from Operation Overlord to V-J Day.', 'Band of Brothers'),
    ('9', 'Jared Harris, Jessie Buckley, Stellan Skarsgård', 'DRAMA', '9.3', 'https://m.media-amazon.com/images/M/MV5BNzU0OTI4YTQtNGQ1ZS00ZjA4LTg3MTMtZjkyZWNjN2RiZDJmXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '1', 'In April 1986, the city of Chernobyl in the Soviet Union suffers one of the worst nuclear disasters in the history of mankind. Consequently, many heroes put their lives on the line in the following days, weeks and months.', 'Chernobyl'),
    ('10', 'Dominic West, Lance Reddick, Sonja Sohn', 'CRIME', '9.3', 'https://m.media-amazon.com/images/M/MV5BZWYyNmRhYjktNjBhNC00M2NhLWEzYmMtZDYwNmIyZTRiZWMzXkEyXkFqcGc@._V1_SX300.jpg', '5', 'The Baltimore drug scene, as seen through the eyes of drug dealers and law enforcement.', 'The Wire'),
    ('11', 'Benedict Cumberbatch, Martin Freeman, Una Stubbs', 'CRIME', '9.0', 'https://m.media-amazon.com/images/M/MV5BNTQzNGZjNDEtOTMwYi00MzFjLWE2ZTYtYzYxYzMwMjZkZDc5XkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', '4', 'In modern-day London, brilliant but eccentric detective Sherlock Holmes teams with war veteran Dr. John Watson to crack baffling crimes, outwit formidable foes, and aid Scotland Yard with razor-sharp deduction.', 'Sherlock'),
    ('12', 'Michael C. Hall, Jennifer Carpenter, David Zayas', 'CRIME', '8.6', 'https://m.media-amazon.com/images/M/MV5BMTQ3YmQ4YzMtOTkyZC00YmM5LThhZjEtM2E0MjFkNTc0OGJhXkEyXkFqcGc@._V1_SX300.jpg', '8', 'He''s smart. He''s lovable. He''s Dexter Morgan, America''s favorite serial killer, who spends his days solving crimes and his nights committing them.', 'Dexter'),
    ('13', 'Noah Wyle, Patrick Ball, Katherine LaNasa', 'DRAMA', '8.9', 'https://m.media-amazon.com/images/M/MV5BMThjMjYxM2YtM2IzZC00NDdmLThiNDYtNzEyNzA0YTRmYTk3XkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '3', 'The daily lives of healthcare professionals in a Pittsburgh hospital as they juggle personal crises, workplace politics, and the emotional toll of treating critically ill patients, revealing the resilience required in their noble ...', 'The Pitt'),
    ('14', 'Jennifer Aniston, Courteney Cox, Lisa Kudrow', 'COMEDY', '8.8', 'https://m.media-amazon.com/images/M/MV5BOTU2YmM5ZjctOGVlMC00YTczLTljM2MtYjhlNGI5YWMyZjFkXkEyXkFqcGc@._V1_QL75_UY562_CR1,0,380,562_.jpg', '10', 'The personal and professional lives of six friends living in the Manhattan borough of New York City.', 'Friends'),
    ('16', 'Zoe Saldaña, Laysla De Oliveira, Dave Annable', 'ACTION', '7.8', 'https://m.media-amazon.com/images/M/MV5BNWJiZDRhMmMtNDMwMy00NTAxLTgxMjktMmUxNDY0OGNmOTg0XkEyXkFqcGc@._V1_QL75_UY562_CR1,0,380,562_.jpg', '3', 'CIA operative Joe McNamara and her team attempt to balance their personal and professional lives as the tip of the spear in the agency''s war on terror.', 'Lioness'),
    ('19', 'Alan Ritchson, Maria Sten, Malcolm Goodwin', 'ACTION', '8.0', 'https://m.media-amazon.com/images/M/MV5BMmE0YTA3MTItMjhiNC00MGQ3LTllZDktNGNiZWY1OWFmNmM1XkEyXkFqcGc@._V1_QL75_UY562_CR35,0,380,562_.jpg', '5', 'Itinerant former military policeman Jack Reacher solves crimes and metes out his own brand of street justice. Based on the novels by Lee Child.', 'Reacher'),
    ('20', 'Matt Smith, Emma D&apos;Arcy, Olivia Cooke', 'ACTION', '8.3', 'https://m.media-amazon.com/images/M/MV5BZGM4MTczODQtNGIxOC00Y2U2LTk1YmItNzA2N2VhYmE0Y2YwXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '4', 'An internal succession war within House Targaryen at the height of its power, 172 years before the birth of Daenerys Targaryen.', 'House of the Dragon'),
    ('21', 'Lior Raz, Itzik Cohen, Netta Garti', 'ACTION', '8.3', 'https://m.media-amazon.com/images/M/MV5BZDNjNzhmM2ItYWM4Ni00ZThjLWE4N2YtODQ1MzRiYWQ0YzBlXkEyXkFqcGc@._V1_SX300.jpg', '5', 'The human stories on both sides of the Israel-Palestine conflict.', 'Fauda'),
    ('22', 'Sterling K. Brown, Sarah Shahi, Nicole Brydon Bloom', 'ACTION', '7.9', 'https://m.media-amazon.com/images/M/MV5BYTNmMjEwZGYtZWJjNy00MjI2LWI3YmUtNTY3NjVkMmU4MDM0XkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '2', 'A Secret Service agent investigates the murder of a former president in a seemingly peaceful community.', 'Paradise'),
    ('23', 'David Boreanaz, Neil Brown Jr., A.J. Buckley', 'ACTION', '7.9', 'https://m.media-amazon.com/images/M/MV5BMDc5ZjUzMTktYzg0MC00MTU3LTkzNzQtYzdiZmZkM2NlOTdjXkEyXkFqcGc@._V1_SX300.jpg', '7', 'The lives of the elite Navy SEALs as they train, plan, and execute the most dangerous, high-stakes missions the United States of America can ask.', 'SEAL Team'),
    ('24', 'Jim Caviezel, Taraji P. Henson, Kevin Chapman', 'ACTION', '8.5', 'https://m.media-amazon.com/images/M/MV5BOTcxNDJiMTUtN2ZhZS00OGE1LWJmZmYtN2VhYThiZTBhYWM1XkEyXkFqcGc@._V1_SX300.jpg', '5', 'An off-the-grid and presumed-dead former CIA agent, John Reese, is hired by a mysterious tech billionaire software genius, Harold Finch, to prevent violent crimes before they happen in New York City via an advanced surveillance so...', 'Person of Interest'),
    ('25', 'Chase Stokes, Madelyn Cline, Madison Bailey', 'ACTION', '7.5', 'https://m.media-amazon.com/images/M/MV5BNzUzMmJmZTQtZjI1Yi00YjdlLWFkMGQtMDkxMjgwNTgxYzZkXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '5', 'On North Carolina''s Outer Banks, a tight-knit group of working-class teenagers known as the Pogues embark on dangerous treasure hunts, uncovering buried secrets, family mysteries, romance, and rivalries while fighting to stay toge...', 'Outer Banks'),
    ('26', 'Karl Urban, Jack Quaid, Antony Starr', 'ACTION', '8.5', 'https://m.media-amazon.com/images/M/MV5BZjU4OWNiYzQtMzc1NS00NjZlLTgyYTctZWY4ZmEzMTkxYjA4XkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', '5', 'A group of vigilantes set out to take down corrupt superheroes who abuse their superpowers.', 'The Boys'),
    ('27', 'Sean Murray, David McCallum, Mark Harmon', 'ACTION', '7.8', 'https://m.media-amazon.com/images/M/MV5BZGExNmI3NDMtMjYxYS00Y2ZmLTlkNmItMGNkNTQ1MzA1ZGM1XkEyXkFqcGc@._V1_SX300.jpg', '24', 'Naval Criminal Investigative Service agents investigate criminal cases connected to Navy and Marine Corps personnel.', 'NCIS'),
    ('28', 'Bella Ramsey, Pedro Pascal, Gabriel Luna', 'ACTION', '8.4', 'https://m.media-amazon.com/images/M/MV5BYWI3ODJlMzktY2U5NC00ZjdlLWE1MGItNWQxZDk3NWNjN2RhXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '3', 'After a global pandemic destroys civilization, a hardened survivor takes charge of a 14-year-old girl who may be humanity''s last hope.', 'The Last of Us'),
    ('29', 'G.W. Bailey, Tony Denison, Michael Paul Chan', 'ACTION', '7.8', 'https://m.media-amazon.com/images/M/MV5BMTExMzA0NTQwMzheQTJeQWpwZ15BbWU3MDMzNzY2MTg@._V1_SX300.jpg', '6', 'The Closer (2005) spin-off series, which follows Captain Raydor of the Los Angeles Police Department.', 'Major Crimes'),
    ('30', 'Tom Welling, Michael Rosenbaum, Allison Mack', 'ACTION', '7.5', 'https://m.media-amazon.com/images/M/MV5BZDU0ZDVjOTItMDNkMy00YTI0LWFjYzItY2M1NjU5NjAzZGViXkEyXkFqcGc@._V1_SX300.jpg', '10', 'A young Clark Kent struggles to find his place in the world as he learns to harness his alien powers for good and deals with the typical troubles of teenage life in Smallville, Kansas.', 'Smallville'),
    ('31', 'Ella Purnell, Aaron Moten, Walton Goggins', 'ACTION', '8.3', 'https://m.media-amazon.com/images/M/MV5BYzE1MTZmY2ItMTgxNi00OGU5LTk4NTItMmY2ODFhYzhjZjRkXkEyXkFqcGc@._V1_QL75_UX380_CR0,57,380,562_.jpg', '3', 'In a future, post-apocalyptic Los Angeles brought about by nuclear decimation, citizens must live in underground bunkers to protect themselves from radiation, mutants and bandits.', 'Fallout'),
    ('32', 'Katheryn Winnick, Gustaf Skarsgård, Alexander Ludwig', 'ACTION', '8.5', 'https://m.media-amazon.com/images/M/MV5BOTFmZmExYTEtYmE0Mi00MzRmLWE4ZDYtOThiNzNlOTIyODljXkEyXkFqcGc@._V1_SX300.jpg', '6', 'Vikings transports us to the brutal and mysterious world of Ragnar Lothbrok, a Viking warrior and farmer who yearns to explore--and raid--the distant shores across the ocean.', 'Vikings'),
    ('33', 'Tom Hiddleston, Owen Wilson, Sophia Di Martino', 'ACTION', '8.2', 'https://m.media-amazon.com/images/M/MV5BYzA2YjM2ZWQtYTZhMS00OTI3LTlhYzQtZjBiZWZkMDdlNjA5XkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '2', 'The mercurial villain Loki resumes his role as the God of Mischief in a new series that takes place after the events of “Avengers: Endgame.”', 'Loki'),
    ('34', 'Nicolas Cage, Lamorne Morris, Li Jun Li', 'ACTION', '7.8', 'https://m.media-amazon.com/images/M/MV5BYjU3NjEwNTItMzc1Mi00Y2QyLTljNDItOTQ4YjU4NjZjN2EyXkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', '1', 'Ben Reilly, a seasoned, down-on-his-luck private investigator in 1930s New York, is forced to grapple with his past life, following a deeply personal tragedy, as the city''s one and only superhero.', 'Spider-Noir'),
    ('35', 'Charlie Cox, Vincent D''Onofrio, Deborah Ann Woll', 'ACTION', '8.6', 'https://m.media-amazon.com/images/M/MV5BODcwOTg2MDE3NF5BMl5BanBnXkFtZTgwNTUyNTY1NjM@._V1_SX300.jpg', '3', 'A blind lawyer by day, vigilante by night. Matt Murdock fights the crime of New York as Daredevil.', 'Daredevil'),
    ('36', 'Pedro Pascal, Chris Bartlett, Katee Sackhoff', 'ACTION', '8.6', 'https://m.media-amazon.com/images/M/MV5BNjgxZGM0OWUtZGY1MS00MWRmLTk2N2ItYjQyZTI1OThlZDliXkEyXkFqcGc@._V1_SX300.jpg', '3', 'The travels of a lone bounty hunter in the outer reaches of the galaxy, far from the authority of the New Republic.', 'The Mandalorian'),
    ('37', 'Colin Farrell, Kirby Howell-Baptiste, Amy Ryan', 'ACTION', '7.4', 'https://m.media-amazon.com/images/M/MV5BNjYyZjQ5MWMtOTE5My00OGZhLTlkMTAtYjEyYWJiNTY5NGY4XkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', '2', 'Private detective John Sugar investigates the disappearance of Olivia, the beloved granddaughter of Hollywood producer Jonathan Siegel. As Sugar tries to determine what happened to Olivia, he unearths Siegel family secrets, old an...', 'Sugar'),
    ('38', 'Alexander Dreymon, Eliza Butterworth, Arnas Fedaravicius', 'ACTION', '8.5', 'https://m.media-amazon.com/images/M/MV5BMjE1MzYzNjk3OF5BMl5BanBnXkFtZTgwMzk0MzYwNzE@._V1_SX300.jpg', '5', 'As Alfred the Great defends his kingdom from Norse invaders, Uhtred--born a Saxon but raised by Vikings--seeks to claim his ancestral birthright.', 'The Last Kingdom'),
    ('39', 'John Cena, Danielle Brooks, Freddie Stroma', 'ACTION', '8.2', 'https://m.media-amazon.com/images/M/MV5BZDIyMGU2NTktOTM3YS00OTRjLWJiMmItNDEyNjVhZTZiZGUxXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '2', 'Picking up where The Suicide Squad (2021) left off, Peacemaker returns home after recovering from his encounter with Bloodsport - only to discover that his freedom comes at a price.', 'Peacemaker'),
    ('40', 'Eliza Taylor, Bob Morley, Marie Avgeropoulos', 'ACTION', '7.5', 'https://m.media-amazon.com/images/M/MV5BNDdmZGYwOWEtN2FkZC00Y2ExLWJkY2UtNzFlODVlNzc3MGIzXkEyXkFqcGc@._V1_SX300.jpg', '7', 'Set 97 years after a nuclear war destroyed civilization, when a spaceship housing humanity''s lone survivors sends 100 juvenile delinquents back to Earth, hoping to repopulate the planet.', 'The 100'),
    ('41', 'Ralph Macchio, William Zabka, Courtney Henggeler', 'ACTION', '8.4', 'https://m.media-amazon.com/images/M/MV5BYjA3NDkwNzktNjJkYi00ODNhLWFhYzQtYzk5NjU4MDM0OWZmXkEyXkFqcGc@._V1_SX300.jpg', '6', 'Decades after their 1984 All Valley Karate Tournament bout, a middle-aged Daniel LaRusso and Johnny Lawrence find themselves martial-arts rivals again.', 'Cobra Kai'),
    ('42', 'Stephen Amell, Katie Cassidy, David Ramsey', 'ACTION', '7.5', 'https://m.media-amazon.com/images/M/MV5BNjRlNjNlY2YtYzQxNS00ZTUzLTkwMTQtMjM0YjZlOWQwZmFkXkEyXkFqcGc@._V1_SX300.jpg', '8', 'Presumed-dead billionaire playboy Oliver Queen returns to Starling City and rights societal wrongs as Arrow.', 'Arrow'),
    ('43', 'Ludivine Sagnier, Soufiane Guerrab, Omar Sy', 'ACTION', '7.5', 'https://m.media-amazon.com/images/M/MV5BMDJhODQ3ZDEtN2JmMS00Yjk5LTk1ZTUtMzI3YTU0NTNjMjAyXkEyXkFqcGc@._V1_SX300.jpg', '4', 'Inspired by the adventures of Arsène Lupin, gentleman thief Assane Diop sets out to avenge his father for an injustice inflicted by a wealthy family.', 'Lupin'),
    ('44', 'Elliot Page, Tom Hopper, David Castañeda', 'ACTION', '7.8', 'https://m.media-amazon.com/images/M/MV5BMzlmMmIxODItYzBjNC00YjMwLWIwOTAtNzVlMTBlNTNkMjZjXkEyXkFqcGc@._V1_SX300.jpg', '4', 'A family of former child heroes, now grown apart, must reunite to continue to protect the world.', 'The Umbrella Academy'),
    ('45', 'Freya Allan, Anya Chalotra, Eamon Farren', 'ACTION', '7.9', 'https://m.media-amazon.com/images/M/MV5BOTQzMzNmMzUtODgwNS00YTdhLTg5N2MtOWU1YTc4YWY3NjRlXkEyXkFqcGc@._V1_SX300.jpg', '5', 'Geralt of Rivia, a solitary monster hunter, struggles to find his place in a world where people often prove more wicked than beasts.', 'The Witcher'),
    ('46', 'Grant Gustin, Candice Patton, Danielle Panabaker', 'ACTION', '7.5', 'https://m.media-amazon.com/images/M/MV5BMjU0ZjZhNDQtMDhkYi00OWQyLWE3NGYtNzBlY2VmM2I4ZDg5XkEyXkFqcGc@._V1_SX300.jpg', '9', 'After being struck by lightning, Barry Allen wakes up from his coma to discover he''s been given the power of super speed, becoming the Flash, and fighting crime in Central City.', 'The Flash'),
    ('48', 'Melissa Benoist, Chyler Leigh, David Harewood', 'ACTION', '6.2', 'https://m.media-amazon.com/images/M/MV5BZGM4MzY3NzYtYjViZS00MmE4LTgxZmMtNTZkNDM5MDIwMDg1XkEyXkFqcGc@._V1_SX300.jpg', '6', 'The adventures of Superman''s cousin and her own superhero career.', 'Supergirl'),
    ('49', 'Oscar Isaac, Ethan Hawke, May Calamawy', 'ACTION', '7.3', 'https://m.media-amazon.com/images/M/MV5BNDAzNmYwZjgtNDc3YS00ZDMyLTk0MjktMTg4MGNmNGU3MjlhXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '1', 'Steven Grant discovers he''s been granted the powers of an Egyptian moon god. But he soon finds out that these newfound powers can be both a blessing and a curse to his troubled life.', 'Moon Knight'),
    ('50', 'Jaz Sinclair, Lizze Broadway, Maddie Phillips', 'ACTION', '7.6', 'https://m.media-amazon.com/images/M/MV5BYWU4YTljYmItYjczNS00MWY0LWI3NjctZjJhYjU3NWNmNWZhXkEyXkFqcGc@._V1_SX300.jpg', '2', 'From the world of "The Boys" comes "Gen V," which explores the first generation of superheroes to know that their super powers are from Compound V. These heroes put their physical and moral boundaries to the test competing for the...', 'Gen V'),
    ('51', 'Jessie James Grelle, Bryce Papenbrook, Trina Nishimura', 'ANIMATION', '9.1', 'https://m.media-amazon.com/images/M/MV5BZjliODY5MzQtMmViZC00MTZmLWFhMWMtMjMwM2I3OGY1MTRiXkEyXkFqcGc@._V1_QL75_UY562_CR9,0,380,562_.jpg', '4', 'In a world where humanity shelters behind towering walls from man-eating Titans, a determined teen joins the elite Survey Corps to fight the giants and uncover the secrets of their origin.', 'Attack on Titan'),
    ('52', 'Jun''ya Enoki, Adam McArthur, Yuma Uchida', 'ANIMATION', '8.5', 'https://m.media-amazon.com/images/M/MV5BMjBlNTExMDAtMWZjZi00MDc5LWFkMjgtZDU0ZWQ5ODk3YWY5XkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', '3', 'After Yuji Itadori swallows a cursed talisman - the finger of a demon - he becomes cursed himself. He enters a shaman''s school to be able to locate the demon''s other body parts and thus exorcise himself.', 'Jujutsu Kaisen'),
    ('53', 'Johnny Yong Bosch, Michelle Ruff, Stephanie Sheh', 'ANIMATION', '8.2', 'https://m.media-amazon.com/images/M/MV5BOWQwOWY5NTUtMjAyZi00YjQzLTkwODgtNmQwZjU1MGIzZDhjXkEyXkFqcGc@._V1_SX300.jpg', '17', 'High school student Ichigo Kurosaki, who has the ability to see ghosts, gains soul reaper powers from Rukia Kuchiki and sets out to save the world from "Hollows".', 'Bleach'),
    ('54', 'Shin''ya Takahashi, Yûto Uemura, Mike Haimoto', 'ANIMATION', '8.8', 'https://m.media-amazon.com/images/M/MV5BNDA3MGNmZTEtMzFiMy00ZmViLThhNmQtMjQ4ZDc5MDEyN2U1XkEyXkFqcGc@._V1_SX300.jpg', '2', 'Following a tragedy, Thorfinn embarks on a journey with the man responsible for it to take his life in a duel as a true and honorable warrior.', 'Vinland Saga'),
    ('55', 'Zach Aguilar, Kenn, Emi Lo', 'ANIMATION', '8.3', 'https://m.media-amazon.com/images/M/MV5BM2JkMzM2ZmYtNWU4MS00MjZhLWFhZWUtYWFjYTJkN2RhZDliXkEyXkFqcGc@._V1_SX300.jpg', '2', 'A Street Kid trying to survive in a technology and body modification-obsessed city of the future. Having everything to lose, he chooses to stay alive by becoming an Edgerunner, a Mercenary outlaw also known as a Cyberpunk.', 'Cyberpunk: Edgerunners'),
    ('56', 'Natsuki Hanae, Zach Aguilar, Abby Trott', 'ANIMATION', '8.5', 'https://m.media-amazon.com/images/M/MV5BMWU1OGEwNmQtNGM3MS00YTYyLThmYmMtN2FjYzQzNzNmNTE0XkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', '4', 'A family is attacked by demons and only two members survive - Tanjiro and his sister Nezuko, who is turning into a demon slowly. Tanjiro sets out to become a demon slayer to avenge his family and cure his sister.', 'Demon Slayer: Kimetsu no Yaiba'),
    ('57', 'Dallas Reid, Gakuto Kajiwara, Jill Harris', 'ANIMATION', '8.2', 'https://m.media-amazon.com/images/M/MV5BZmZkZjNhMWMtM2U0Mi00MjdlLTk3NmMtMTMwZjgwOTJmODMzXkEyXkFqcGc@._V1_SX300.jpg', '4', 'Asta and Yuno were abandoned together at the same church and have been inseparable since. As children, they promised that they would compete against each other to see who would become the next Emperor Magus.', 'Black Clover'),
    ('58', 'Marc Diraison, Nobutoshi Canna, Carrie Keranen', 'ANIMATION', '8.7', 'https://m.media-amazon.com/images/M/MV5BMzEzMzhkNDgtY2Q0YS00MDk0LTg0YzItODY5ZjNjMDc4ODI3XkEyXkFqcGc@._V1_SX300.jpg', '1', 'Guts, a wandering mercenary, joins the Band of the Hawk after being defeated in a duel by Griffith, the group''s leader and founder. Together, they dominate every battle, but something menacing lurks in the shadows.', 'Berserk'),
