    ('119', 'Seth MacFarlane, Adrianne Palicki, Penny Johnson Jerald', 'ADVENTURE', '8.0', 'https://m.media-amazon.com/images/M/MV5BMWU4MDAxMDktNTBjZi00ZTg3LWEzYzItZjkyMjNhMWViMTcwXkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', '3', 'Set 400 years in the future, the crew of the U.S.S. Orville continue their mission of exploration, navigating both the mysteries of the universe, and the complexities of their own interpersonal relationships.', 'The Orville'),
    ('120', 'Fred Tatasciore, Scott Whyte, Emily O&apos;Brien', 'ANIMATION', '8.4', 'https://m.media-amazon.com/images/M/MV5BZDY3OTZiYzktN2U5My00MzRhLWJiZjItZjNlZmM3OGViZmFiXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '4', 'A collection of animated short stories that span various genres including science fiction, fantasy, horror and comedy.', 'Love, Death & Robots'),
    ('121', 'John Hurt, Colin Morgan, Bradley James', 'ADVENTURE', '7.9', 'https://m.media-amazon.com/images/M/MV5BNmI5NDgyZmQtNDc3YS00Mjg0LThmMzEtZjcyNzczOTJlYWY4XkEyXkFqcGc@._V1_SX300.jpg', '5', 'In a medieval kingdom where magic is punishable by death, young sorcerer Merlin, manservant to Prince Arthur and ward of the court physician, meets a dragon and finds he is apart of a great prophecy to bring about the golden age o...', 'Merlin'),
    ('122', 'Emily Beecham, Aneurin Barnard, Andreas Pietschmann', 'ADVENTURE', '7.3', 'https://m.media-amazon.com/images/M/MV5BY2UyM2YwZTEtOTk5Zi00ODhkLTg2ZjctMzIxMTViZjFmN2Y4XkEyXkFqcGc@._V1_SX300.jpg', '1', 'Multinational immigrants traveling from the old continent to the new encounter a nightmarish riddle aboard a second ship adrift on the open sea.', '1899'),
    ('123', 'Danielle Rose Russell, Aria Shahghasemi, Jenny Boyd', 'ADVENTURE', '7.2', 'https://m.media-amazon.com/images/M/MV5BZmMzYzYwMjItOWRiNi00NmU3LWI2ZjktOWFjYzI5ZmI4ZDI0XkEyXkFqcGc@._V1_SX300.jpg', '4', 'Hope Mikaelson, a tribrid daughter of a Vampire/Werewolf hybrid, makes her way in the world.', 'Legacies'),
    ('124', 'Molly Parker, Toby Stephens, Maxwell Jenkins', 'ADVENTURE', '7.3', 'https://m.media-amazon.com/images/M/MV5BMTU1MzAwODM4OF5BMl5BanBnXkFtZTgwMjA4OTY5NDM@._V1_SX300.jpg', '3', 'After crash-landing on an alien planet, the Robinson family fight against all odds to survive and escape, but they''re surrounded by hidden dangers.', 'Lost in Space'),
    ('125', 'Jared Padalecki, Jensen Ackles, Jim Beaver', 'DRAMA', '8.4', 'https://m.media-amazon.com/images/M/MV5BMDFmMGZmMGItNGRjNC00NjVjLWI5ODEtNzhjMTE5MmJhN2FkXkEyXkFqcGc@._V1_QL75_UY562_CR3,0,380,562_.jpg', '15', 'Two brothers follow their father''s footsteps as hunters, fighting evil supernatural beings of many kinds, including monsters, demons, and gods that roam the earth.', 'Supernatural'),
    ('126', 'Harold Perrineau, Catalina Sandino Moreno, David Alpay', 'DRAMA', '7.8', 'https://m.media-amazon.com/images/M/MV5BNDAwNDljNWEtNWE1Zi00YjFlLWEzM2UtY2E3ZTM1MTcxMTcyXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '5', 'A town with a hidden secret experiences strange occurrences that intensify at night. Mysterious forces disrupt everyday routines as residents try to preserve stability and community while attempting to comprehend their surroundings.', 'From'),
    ('127', 'Jenna Ortega, Emma Myers, Hunter Doohan', 'COMEDY', '8.0', 'https://m.media-amazon.com/images/M/MV5BY2E1NDI5OWEtODJmYi00Nzg2LWI4MjUtODFiMTU2YWViOTU3XkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', '3', 'Follows Wednesday Addams'' years as a student, when she attempts to master her emerging psychic ability, thwart a killing spree, and solve the mystery that embroiled her parents.', 'Wednesday'),
    ('128', 'Brandon Scott, Abigail Pniowsky, Marina Stephenson Kerr', 'DRAMA', '7.1', 'https://m.media-amazon.com/images/M/MV5BMjExMTMxNjMwNl5BMl5BanBnXkFtZTgwNDA2OTYzNjM@._V1_SX300.jpg', '4', 'An anthology series based on creepypastas.', 'Channel Zero'),
    ('130', 'Claire Foy, Olivia Colman, Imelda Staunton', 'BIOGRAPHY', '8.6', 'https://m.media-amazon.com/images/M/MV5BODcyODZlZDMtZGE0Ni00NjBhLWJlYTAtZDdlNWY3MzkwMGVhXkEyXkFqcGc@._V1_SX300.jpg', '6', 'Follows the political rivalries and romances of Queen Elizabeth II''s reign and the events that shaped Britain for the second half of the 20th century.', 'The Crown'),
    ('131', 'Elizabeth Tabish, George H. Xanthis, Shahar Isaac', 'BIOGRAPHY', '9.1', 'https://m.media-amazon.com/images/M/MV5BMDRiNmVjYmQtZDQ3Yy00MjA5LWFhYWYtYWMxYTE1NzEyZDNiXkEyXkFqcGc@._V1_QL75_UX380_CR0,57,380,562_.jpg', '7', 'The Chosen is a historical drama based on the life of Jesus and those who knew him. Set against the backdrop of Roman oppression in first-century Israel, the series shares an authentic look at Jesus'' revolutionary life and teachings.', 'The Chosen'),
    ('133', 'Elle Fanning, Phoebe Fox, Gwilym Lee', 'BIOGRAPHY', '8.1', 'https://m.media-amazon.com/images/M/MV5BNTMzYTNiODktNmMyOC00NGVjLWE0ZmYtMzJjN2JhODI1MjYzXkEyXkFqcGc@._V1_SX300.jpg', '3', 'A royal woman living in rural Russia during the 18th century is forced to choose between her own personal happiness and the future of Russia, when she marries an Emperor.', 'The Great'),
    ('134', 'Anthony Boyle, Emily Fairn, Louis Partridge', 'BIOGRAPHY', '7.4', 'https://m.media-amazon.com/images/M/MV5BM2IzZDg0ODYtYWUyZi00YmJmLWE2N2MtMmRmNjAzMWRiYTAzXkEyXkFqcGc@._V1_SX300.jpg', '1', 'Follows the aftermath of the death of brewery mogul, Sir Benjamin Guinness, and the profound impact of his will on the fate of his four adult children: Arthur, Edward, Anne and Ben.', 'House of Guinness'),
    ('136', 'Scoot McNairy, José María Yazpik, Alejandro Edda', 'BIOGRAPHY', '8.3', 'https://m.media-amazon.com/images/M/MV5BM2FkZGQyODItOGFlNy00ZDA1LWFjMTEtMGUyYzk0ZDYzNmRjXkEyXkFqcGc@._V1_SX300.jpg', '3', 'The rise of the Guadalajara Cartel as an American DEA agent learns the danger of targeting narcos in Mexico.', 'Narcos: Mexico'),
    ('137', 'Keeley Hawes, Josh O''Connor, Milo Parker', 'BIOGRAPHY', '8.2', 'https://m.media-amazon.com/images/M/MV5BYjkwN2U4ODItMzY2Mi00OGU5LWFjNjQtMjc4Nzc4OWEzMDY4XkEyXkFqcGc@._V1_SX300.jpg', '4', 'Louisa Durrell raises her four children single-handedly after her husband''s death. Following a financial crisis, the family moves to the Greek island of Corfu and tries to adapt to life there.', 'The Durrells'),
    ('138', 'Daniel Sharman, Alessandra Mastronardi, Synnove Karlsen', 'BIOGRAPHY', '7.8', 'https://m.media-amazon.com/images/M/MV5BNGI2ZTFmY2YtNDRhZS00MjcxLWE2ZGYtOWMxMGQwMTcwNDY5XkEyXkFqcGc@._V1_SX300.jpg', '3', 'A political family drama set in Florence in the early fifteenth century. Cosimo de Medici finds himself at the helm of his banking dynasty when his father, Giovanni, dies suddenly.', 'Medici');

